import{_ as l,o as e,c as t,O as i}from"./chunks/framework.ccd0435f.js";const r="/pms-doc/assets/gcj-zr-zjrw.bc8a3893.png",o="/pms-doc/assets/gcj-zr-zjrw2.0bc74885.png",p="/pms-doc/assets/gcj-zr-zjmx.ccdc9990.png",b=JSON.parse('{"title":"过程检安排","description":"","frontmatter":{},"headers":[],"relativePath":"品质管理/过程检安排.md","filePath":"品质管理/过程检安排.md"}'),s={name:"品质管理/过程检安排.md"};function c(n,a,h,d,u,_){return e(),t("div",null,a[0]||(a[0]=[i('<h1 id="过程检安排" tabindex="-1">过程检安排 <a class="header-anchor" href="#过程检安排" aria-label="Permalink to &quot;过程检安排&quot;">​</a></h1><blockquote><p>生产完成员工报工时，如果这个工序配置了检验项时，会带到过程检安排列表</p></blockquote><h4 id="_1-批量分发" tabindex="-1">1.批量分发 <a class="header-anchor" href="#_1-批量分发" aria-label="Permalink to &quot;1.批量分发&quot;">​</a></h4><ul><li><p>勾选序号前的勾选框触发批量分发按钮可进行分发</p><p>-单号与工序均不一致的情况下，不能批量派工</p></li><li><p>选择检验类型，检验员，分发量，要求完成时间，备注信息等可提交分发</p><p>-全检指的是检验所有的产品</p><p>-抽检指的是输入百分比抽取部分产品进行检验</p><p>-免检指的是不用检验直接入库</p></li><li><p>一个任务可分发多个检验员，如果选择多明检验员时，填写分发量时，在弹窗中分配分发数量</p></li></ul><h4 id="_2-分发" tabindex="-1">2.分发 <a class="header-anchor" href="#_2-分发" aria-label="Permalink to &quot;2.分发&quot;">​</a></h4><ul><li><p>点击分发按钮选择检验类型，要求完成时间</p></li><li><p>可添加给多个检验人员</p><p>-分发数量不能超过抽检数量</p></li><li><p>检验类型分为全检、抽检、免检</p><p>-全检指的是检验所有的产品</p><p>-抽检指的是输入百分比抽取部分产品进行检验</p><p>-免检指的是不用检验直接入库</p></li></ul><p><img src="'+r+'" alt="rtss"></p><h4 id="_3-已检量" tabindex="-1">3.已检量 <a class="header-anchor" href="#_3-已检量" aria-label="Permalink to &quot;3.已检量&quot;">​</a></h4><ul><li><p>查看所分发员工完成就检验量</p></li><li><p>存在分发给多个员工去完成</p></li></ul><h4 id="_4-合格量" tabindex="-1">4.合格量 <a class="header-anchor" href="#_4-合格量" aria-label="Permalink to &quot;4.合格量&quot;">​</a></h4><ul><li>查看所分发员工完成的合格量</li><li>存在分发给多个员工去完成</li></ul><h4 id="_5-检验准则" tabindex="-1">5.检验准则 <a class="header-anchor" href="#_5-检验准则" aria-label="Permalink to &quot;5.检验准则&quot;">​</a></h4><ul><li>点击可查看这道工序下所配置的检验项</li></ul><h4 id="_6-表头自定义设置" tabindex="-1">6.表头自定义设置 <a class="header-anchor" href="#_6-表头自定义设置" aria-label="Permalink to &quot;6.表头自定义设置&quot;">​</a></h4><ul><li>点击表头设置图标可更改表头字段的显示/隐藏</li></ul><p><img src="'+o+'" alt="rtss"></p><h1 id="质检明细" tabindex="-1">质检明细 <a class="header-anchor" href="#质检明细" aria-label="Permalink to &quot;质检明细&quot;">​</a></h1><blockquote><p>质检明中记录着每个产品/物料检验的详细记录</p></blockquote><h4 id="_1-导出" tabindex="-1">1.导出 <a class="header-anchor" href="#_1-导出" aria-label="Permalink to &quot;1.导出&quot;">​</a></h4><ul><li><p>先点击导出图标，触发勾选框</p><p>-可手动输入n条导出，或手动勾选导出</p></li></ul><h4 id="_2-操作工" tabindex="-1">2.操作工 <a class="header-anchor" href="#_2-操作工" aria-label="Permalink to &quot;2.操作工&quot;">​</a></h4><ul><li>悬浮人员名称可查看这个操作工的基本信息</li></ul><p><img src="'+p+'" alt="rtss"></p>',23)]))}const q=l(s,[["render",c]]);export{b as __pageData,q as default};
